CREATE TABLE academic_years(id integer PRIMARY KEY,start_date date NOT NULL,end_date date NOT NULL,active boolean NOT NULL);
INSERT INTO academic_years VALUES(2026,'2026-08-01','2027-07-31',true),(2027,'2027-08-01','2028-07-31',true);
CREATE TABLE campuses(id varchar(20) PRIMARY KEY,provider varchar(8) NOT NULL REFERENCES providers(id),name varchar(100) NOT NULL);
INSERT INTO campuses VALUES('A-CENTRAL','A','Aster Central Campus'),('B-NORTH','B','Birch North Campus');
CREATE TABLE qualifications(id varchar(20) PRIMARY KEY,title varchar(100) NOT NULL);
INSERT INTO qualifications VALUES('CERT','Demo Certificate'),('DIP','Demo Diploma');
CREATE TABLE course_variants(id uuid PRIMARY KEY,course_id varchar(20) NOT NULL REFERENCES courses(id),campus_id varchar(20) NOT NULL REFERENCES campuses(id),academic_year integer NOT NULL REFERENCES academic_years(id),qualification_id varchar(20) NOT NULL REFERENCES qualifications(id),UNIQUE(course_id,campus_id,academic_year));
CREATE TABLE modules(id varchar(20) PRIMARY KEY,provider varchar(8) NOT NULL REFERENCES providers(id),title varchar(100) NOT NULL,credits integer NOT NULL CHECK(credits BETWEEN 1 AND 180));
INSERT INTO modules VALUES('A-DATA','A','Data fundamentals',30),('B-ML','B','Machine learning foundations',30);
CREATE TABLE course_modules(course_id varchar(20) NOT NULL REFERENCES courses(id),module_id varchar(20) NOT NULL REFERENCES modules(id),PRIMARY KEY(course_id,module_id));
INSERT INTO course_modules VALUES('A-CS','A-DATA'),('B-DS','B-ML');
CREATE TABLE subscriptions(id uuid PRIMARY KEY,provider varchar(8) NOT NULL REFERENCES providers(id),academic_year integer NOT NULL REFERENCES academic_years(id),service varchar(20) NOT NULL,active boolean NOT NULL,UNIQUE(provider,academic_year,service));
CREATE TABLE students(id uuid PRIMARY KEY,provider varchar(8) NOT NULL REFERENCES providers(id),demo_label varchar(100) NOT NULL,created_at timestamp with time zone NOT NULL);
ALTER TABLE applications ADD COLUMN student_id uuid REFERENCES students(id);
CREATE TABLE tuition_periods(id uuid PRIMARY KEY,application_id uuid NOT NULL UNIQUE REFERENCES applications(id),provider varchar(8) NOT NULL,start_date date NOT NULL,end_date date NOT NULL,status varchar(30) NOT NULL);
CREATE TABLE tuition_finance_details(id uuid PRIMARY KEY,tuition_period_id uuid NOT NULL UNIQUE REFERENCES tuition_periods(id),fee decimal(12,2) NOT NULL,currency varchar(3) NOT NULL,credits integer NOT NULL);
CREATE TABLE tuition_period_histories(id uuid PRIMARY KEY,tuition_period_id uuid NOT NULL REFERENCES tuition_periods(id),status varchar(30) NOT NULL,fee decimal(12,2) NOT NULL,credits integer NOT NULL,event varchar(60) NOT NULL,occurred_at timestamp with time zone NOT NULL);
CREATE TABLE rule_configs(id varchar(40) PRIMARY KEY,description varchar(200) NOT NULL,enabled boolean NOT NULL,policy varchar(30) NOT NULL);
INSERT INTO rule_configs VALUES('REG_BEFORE_ATN','Registration required before attendance',true,'DEMO_ASSUMPTION'),('SUSPEND_REQUIRES_ATN','Confirmed attendance before suspension',true,'DEMO_ASSUMPTION'),('GBP_SPLIT','25 percent, 25 percent, exact remainder',true,'DEMO_ASSUMPTION');
CREATE TABLE feature_toggles(name varchar(60) PRIMARY KEY,toggle_value varchar(40) NOT NULL);
INSERT INTO feature_toggles VALUES('DEMO_LOCAL_RECEIVERS','ENABLED'),('DEMO_EXTERNAL_NETWORK','DISABLED');
CREATE TABLE sync_exceptions(id uuid PRIMARY KEY,provider varchar(8) NOT NULL,service varchar(40) NOT NULL,error_code varchar(40) NOT NULL,message_masked varchar(200) NOT NULL,created_at timestamp with time zone NOT NULL);
ALTER TABLE outbox_events ADD COLUMN target varchar(40) NOT NULL DEFAULT 'MULE';
ALTER TABLE outbox_events ADD COLUMN next_attempt timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP;
ALTER TABLE outbox_events ADD COLUMN last_error varchar(200);
